    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 5 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                rr, cc = stack.pop()
                cells.append((rr, cc))
                for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
                    nr, nc = rr + dr, cc + dc
                    if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 5 and (nr, nc) not in seen:
                        seen.add((nr, nc))
                        stack.append((nr, nc))
            r0, r1 = min(rr for rr, _ in cells), max(rr for rr, _ in cells)
            c0, c1 = min(cc for _, cc in cells), max(cc for _, cc in cells)
            if r1 - r0 < 2 or c1 - c0 < 2:
                continue
            # Identify the frame: solid sides and bottom, with one opening on top.
            if not all(grid[rr][c0] == 5 and grid[rr][c1] == 5 for rr in range(r0, r1 + 1)):
                continue
            if not all(grid[r1][cc] == 5 for cc in range(c0, c1 + 1)):
                continue
            gaps = [cc for cc in range(c0, c1 + 1) if grid[r0][cc] == 0]
            if len(gaps) != 1:
                continue
            gap = gaps[0]
            if any(grid[rr][cc] != 0 for rr in range(r0 + 1, r1) for cc in range(c0 + 1, c1)):
                continue
            # Fill the opening and hollow center, then extend its color ray left.
            out[r0][gap] = 2
            for rr in range(r0 + 1, r1):
                for cc in range(c0 + 1, c1):
                    out[rr][cc] = 2
            if r0 > 0:
                for cc in range(gap + 1):
                    out[r0 - 1][cc] = 2
    return out
